var liveSupply=new SharedSubmarineSupplies("ar-c",supplyNow,new("987",0,2,37,140));
var cachedSupply=new SharedCachedVoyage("ar-c","Member","Rafflesia","Empire",supplyNow.AddMinutes(2),arCache with {InventorySpace=90});
